import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { securityHeaders, generateNonce, getCSPPolicy, CSP_POLICIES } from './security';
import type { Context } from 'hono';

/**
 * Unit Tests for Security Middleware
 *
 * Tests CSP header generation, security headers, environment-based policies,
 * and middleware behavior.
 *
 * Coverage targets:
 * - CSP header generation for development environment
 * - CSP header generation for production environment
 * - All security headers included
 * - Nonce generation
 * - Report-only mode
 * - Configuration options
 * - Environment variable support
 */

describe('Security Middleware', () => {
  // Store original environment variables
  const originalEnv = { ...process.env };

  beforeEach(() => {
    vi.clearAllMocks();
    // Reset environment to defaults
    process.env = { ...originalEnv };
  });

  afterEach(() => {
    // Restore original environment
    process.env = originalEnv;
  });

  /**
   * Mock Hono Context
   *
   * Creates a mock context object that simulates Hono's request/response context.
   */
  function createMockContext(): {
    context: Partial<Context>;
    headers: Map<string, string>;
    storage: Map<string, unknown>;
  } {
    const headers = new Map<string, string>();
    const storage = new Map<string, unknown>();

    const context: Partial<Context> = {
      header: vi.fn((key: string, value: string) => {
        headers.set(key, value);
      }),
      set: vi.fn((key: string, value: unknown) => {
        storage.set(key, value);
      }),
      get: vi.fn((key: string) => storage.get(key)),
    };

    return { context, headers, storage };
  }

  describe('generateNonce', () => {
    it('should generate a nonce', () => {
      const nonce = generateNonce();

      expect(nonce).toBeDefined();
      expect(typeof nonce).toBe('string');
      expect(nonce.length).toBeGreaterThan(0);
    });

    it('should generate unique nonces', () => {
      const nonce1 = generateNonce();
      const nonce2 = generateNonce();

      expect(nonce1).not.toBe(nonce2);
    });

    it('should generate base64-encoded nonces', () => {
      const nonce = generateNonce();

      // Base64 regex: alphanumeric, +, /, and = for padding
      const base64Regex = /^[A-Za-z0-9+/=]+$/;
      expect(nonce).toMatch(base64Regex);
    });

    it('should generate nonces of consistent length', () => {
      const nonce1 = generateNonce();
      const nonce2 = generateNonce();

      expect(nonce1.length).toBe(nonce2.length);
    });
  });

  describe('getCSPPolicy', () => {
    it('should return development policy for "development" environment', () => {
      const policy = getCSPPolicy('development');

      expect(policy).toContain("'unsafe-inline'");
      expect(policy).toContain("'unsafe-eval'");
      expect(policy).toContain('localhost:3000');
      expect(policy).toContain('ws://localhost:5173');
      expect(policy).not.toContain('upgrade-insecure-requests');
    });

    it('should return production policy for "production" environment', () => {
      const policy = getCSPPolicy('production');

      expect(policy).not.toContain("'unsafe-eval'");
      expect(policy).not.toContain('localhost');
      expect(policy).not.toContain('ws://localhost');
      expect(policy).toContain('upgrade-insecure-requests');
    });

    it('should return production policy for unknown environments', () => {
      const policy = getCSPPolicy('staging');

      expect(policy).not.toContain("'unsafe-eval'");
      expect(policy).toContain('upgrade-insecure-requests');
    });

    it('should inject nonce into script-src when provided', () => {
      const nonce = 'abc123';
      const policy = getCSPPolicy('production', nonce);

      expect(policy).toContain(`'nonce-${nonce}'`);
      expect(policy).toMatch(/script-src[^;]*'nonce-abc123'/);
    });

    it('should include all required CSP directives', () => {
      const policy = getCSPPolicy('production');

      const requiredDirectives = [
        'default-src',
        'script-src',
        'style-src',
        'img-src',
        'font-src',
        'connect-src',
        'frame-ancestors',
        'base-uri',
        'form-action',
        'object-src',
      ];

      requiredDirectives.forEach((directive) => {
        expect(policy).toContain(directive);
      });
    });

    it('should allowlist AI service domains', () => {
      const policy = getCSPPolicy('production');

      const aiDomains = [
        'openrouter.ai',
        'api.replicate.com',
        'generativelanguage.googleapis.com',
        'api.openai.com',
      ];

      aiDomains.forEach((domain) => {
        expect(policy).toContain(domain);
      });
    });

    it('should allowlist Google Fonts', () => {
      const policy = getCSPPolicy('production');

      expect(policy).toContain('fonts.googleapis.com');
      expect(policy).toContain('fonts.gstatic.com');
    });

    it('should allow blob: and data: URLs for images', () => {
      const policy = getCSPPolicy('production');

      expect(policy).toMatch(/img-src[^;]*blob:/);
      expect(policy).toMatch(/img-src[^;]*data:/);
    });
  });

  describe('CSP_POLICIES export', () => {
    it('should export pre-built development policy', () => {
      expect(CSP_POLICIES.development).toBeDefined();
      expect(typeof CSP_POLICIES.development).toBe('string');
      expect(CSP_POLICIES.development).toContain("'unsafe-inline'");
    });

    it('should export pre-built production policy', () => {
      expect(CSP_POLICIES.production).toBeDefined();
      expect(typeof CSP_POLICIES.production).toBe('string');
      expect(CSP_POLICIES.production).not.toContain("'unsafe-eval'");
    });
  });

  describe('securityHeaders middleware', () => {
    describe('CSP header generation', () => {
      it('should set CSP header in development environment', async () => {
        process.env.NODE_ENV = 'development';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toBeDefined();
        expect(cspHeader).toContain("'unsafe-inline'");
        expect(cspHeader).toContain("'unsafe-eval'");
      });

      it('should set CSP header in production environment', async () => {
        process.env.NODE_ENV = 'production';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toBeDefined();
        expect(cspHeader).not.toContain("'unsafe-eval'");
        expect(cspHeader).toContain('upgrade-insecure-requests');
      });

      it('should use enforce mode by default', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.has('Content-Security-Policy')).toBe(true);
        expect(headers.has('Content-Security-Policy-Report-Only')).toBe(false);
      });

      it('should use report-only mode when configured', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ mode: 'report-only' });
        await middleware(context as Context, next);

        expect(headers.has('Content-Security-Policy-Report-Only')).toBe(true);
        expect(headers.has('Content-Security-Policy')).toBe(false);
      });

      it('should add report-uri when configured', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ reportUri: '/api/csp-report' });
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain('report-uri /api/csp-report');
      });

      it('should generate and store nonce when useNonce is true', async () => {
        const { context, headers, storage } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ useNonce: true });
        await middleware(context as Context, next);

        const nonce = storage.get('cspNonce');
        expect(nonce).toBeDefined();
        expect(typeof nonce).toBe('string');

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain(`'nonce-${nonce}'`);
      });

      it('should not generate nonce when useNonce is false', async () => {
        const { context, storage } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ useNonce: false });
        await middleware(context as Context, next);

        const nonce = storage.get('cspNonce');
        expect(nonce).toBeUndefined();
      });
    });

    describe('additional security headers', () => {
      it('should set X-Frame-Options header', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.get('X-Frame-Options')).toBe('DENY');
      });

      it('should set X-Content-Type-Options header', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.get('X-Content-Type-Options')).toBe('nosniff');
      });

      it('should set X-XSS-Protection header', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.get('X-XSS-Protection')).toBe('1; mode=block');
      });

      it('should set Referrer-Policy header', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.get('Referrer-Policy')).toBe('strict-origin-when-cross-origin');
      });

      it('should set Permissions-Policy header', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const permissionsPolicy = headers.get('Permissions-Policy');
        expect(permissionsPolicy).toContain('camera=()');
        expect(permissionsPolicy).toContain('microphone=()');
        expect(permissionsPolicy).toContain('geolocation=()');
        expect(permissionsPolicy).toContain('payment=()');
      });

      it('should set all 6 security headers', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const expectedHeaders = [
          'Content-Security-Policy',
          'X-Frame-Options',
          'X-Content-Type-Options',
          'X-XSS-Protection',
          'Referrer-Policy',
          'Permissions-Policy',
        ];

        expectedHeaders.forEach((header) => {
          expect(headers.has(header)).toBe(true);
        });
      });
    });

    describe('environment variable support', () => {
      it('should respect CSP_ENABLED environment variable', async () => {
        process.env.CSP_ENABLED = 'false';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.size).toBe(0);
        expect(next).toHaveBeenCalled();
      });

      it('should enable CSP when CSP_ENABLED is true', async () => {
        process.env.CSP_ENABLED = 'true';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.has('Content-Security-Policy')).toBe(true);
      });

      it('should respect CSP_MODE environment variable', async () => {
        process.env.CSP_MODE = 'report-only';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(headers.has('Content-Security-Policy-Report-Only')).toBe(true);
      });

      it('should respect CSP_REPORT_URI environment variable', async () => {
        process.env.CSP_REPORT_URI = '/api/csp-violations';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain('report-uri /api/csp-violations');
      });

      it('should use production policy when NODE_ENV is production', async () => {
        process.env.NODE_ENV = 'production';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).not.toContain("'unsafe-eval'");
      });

      it('should use development policy when NODE_ENV is development', async () => {
        process.env.NODE_ENV = 'development';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain("'unsafe-eval'");
      });
    });

    describe('configuration precedence', () => {
      it('should prefer config.enabled over CSP_ENABLED environment variable', async () => {
        process.env.CSP_ENABLED = 'true';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ enabled: false });
        await middleware(context as Context, next);

        expect(headers.size).toBe(0);
      });

      it('should prefer config.mode over CSP_MODE environment variable', async () => {
        process.env.CSP_MODE = 'report-only';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ mode: 'enforce' });
        await middleware(context as Context, next);

        expect(headers.has('Content-Security-Policy')).toBe(true);
        expect(headers.has('Content-Security-Policy-Report-Only')).toBe(false);
      });

      it('should prefer config.reportUri over CSP_REPORT_URI environment variable', async () => {
        process.env.CSP_REPORT_URI = '/api/env-report';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ reportUri: '/api/config-report' });
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain('/api/config-report');
        expect(cspHeader).not.toContain('/api/env-report');
      });
    });

    describe('middleware behavior', () => {
      it('should call next() after setting headers', async () => {
        const { context } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        expect(next).toHaveBeenCalledTimes(1);
      });

      it('should call next() immediately when disabled', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ enabled: false });
        await middleware(context as Context, next);

        expect(next).toHaveBeenCalledTimes(1);
        expect(headers.size).toBe(0);
      });

      it('should be async', async () => {
        const { context } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        const result = middleware(context as Context, next);

        expect(result).toBeInstanceOf(Promise);
        await result;
      });
    });

    describe('edge cases', () => {
      it('should handle missing NODE_ENV', async () => {
        delete process.env.NODE_ENV;
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        // Should default to production policy
        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).not.toContain("'unsafe-eval'");
      });

      it('should handle empty reportUri', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({ reportUri: '' });
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).not.toContain('report-uri');
      });

      it('should handle both useNonce and reportUri', async () => {
        const { context, headers, storage } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({
          useNonce: true,
          reportUri: '/api/csp-report',
        });
        await middleware(context as Context, next);

        const nonce = storage.get('cspNonce');
        const cspHeader = headers.get('Content-Security-Policy');

        expect(nonce).toBeDefined();
        expect(cspHeader).toContain(`'nonce-${nonce}'`);
        expect(cspHeader).toContain('report-uri /api/csp-report');
      });

      it('should handle report-only mode with reportUri', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders({
          mode: 'report-only',
          reportUri: '/api/csp-violations',
        });
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy-Report-Only');
        expect(cspHeader).toContain('report-uri /api/csp-violations');
      });
    });

    describe('security policy validation', () => {
      it('should not include unsafe-eval in production script-src', async () => {
        process.env.NODE_ENV = 'production';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        const scriptSrcMatch = cspHeader?.match(/script-src ([^;]+)/);
        expect(scriptSrcMatch).toBeDefined();
        expect(scriptSrcMatch?.[1]).not.toContain("'unsafe-eval'");
      });

      it('should include upgrade-insecure-requests in production', async () => {
        process.env.NODE_ENV = 'production';
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toContain('upgrade-insecure-requests');
      });

      it('should set frame-ancestors to none', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toMatch(/frame-ancestors[^;]*'none'/);
      });

      it('should set object-src to none', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toMatch(/object-src[^;]*'none'/);
      });

      it('should restrict base-uri to self', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toMatch(/base-uri[^;]*'self'/);
      });

      it('should restrict form-action to self', async () => {
        const { context, headers } = createMockContext();
        const next = vi.fn();

        const middleware = securityHeaders();
        await middleware(context as Context, next);

        const cspHeader = headers.get('Content-Security-Policy');
        expect(cspHeader).toMatch(/form-action[^;]*'self'/);
      });
    });
  });

  describe('code coverage', () => {
    it('should achieve high code coverage for generateNonce', () => {
      // Test multiple times to ensure consistent behavior
      for (let i = 0; i < 10; i++) {
        const nonce = generateNonce();
        expect(nonce).toBeDefined();
        expect(nonce.length).toBeGreaterThan(0);
      }
    });

    it('should achieve high code coverage for getCSPPolicy', () => {
      // Test all environment variations
      const environments = ['development', 'production', 'test', 'staging'];
      environments.forEach((env) => {
        const policy = getCSPPolicy(env);
        expect(policy).toBeDefined();
        expect(policy.length).toBeGreaterThan(0);
      });

      // Test with nonce
      const policyWithNonce = getCSPPolicy('production', 'test-nonce');
      expect(policyWithNonce).toContain('test-nonce');
    });

    it('should achieve high code coverage for securityHeaders', async () => {
      const configurations = [
        {},
        { enabled: true },
        { enabled: false },
        { mode: 'enforce' as const },
        { mode: 'report-only' as const },
        { reportUri: '/api/csp' },
        { useNonce: true },
        { useNonce: false },
        { enabled: true, mode: 'report-only' as const, reportUri: '/api/csp', useNonce: true },
      ];

      for (const config of configurations) {
        const { context } = createMockContext();
        const next = vi.fn();
        const middleware = securityHeaders(config);
        await middleware(context as Context, next);
        expect(next).toHaveBeenCalled();
      }
    });
  });
});
